function solve(nums) {
  let maxHere = nums[0], minHere = nums[0], best = nums[0];
  for (let i = 1; i < nums.length; i++) {
    const x = nums[i];
    const a = maxHere * x, b = minHere * x;
    maxHere = Math.max(x, a, b);
    minHere = Math.min(x, a, b);
    best = Math.max(best, maxHere);
  }
  return best;
}
